                pronunciationBn = "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিঁও ওয়া আলা আলি মুহাম্মাদ...",
                meaningBn = "বৃহস্পতিবার মাগরিবের সাথে সাথেই জুমু'আর দিন শুরু হয়ে যায়। এখন থেকেই এই আমল শুরু করতে পারি দু'আ কবুলের জন্য। তাহলে কালকে সূর্যাস্তের পূর্বেই ১০০০ বার দুরুদ পড়া সহজ হয়ে যাবে ইনশাআল্লাহ। চেষ্টা করবেন জুমু'আর দিন সূর্যাস্তের পূর্বেই আমলটি শেষ করার এবং দু'আ করার।\n\nরাসূলুল্লাহ ﷺ বলেন:\n“জুমু'আর দিনে এমন একটি সময় রয়েছে, যেখানে এমন কোনো মুসলিম নাই যে, সে যদি তখন আল্লাহর নিকট কিছু চায়, আল্লাহ তাকে দিবেন না। আর তোমরা আসরের পরে (মাগরিবের আগের) সে সময়টা তালাশ করো।” (আবু দাউদ)\n\nএই আমলের মাধ্যমে রাসুল (ﷺ) এর উপর দুরুদও পড়ার সাথে সাথে দু'আ কবুলের আমলও করা হয়ে যাবে ইনশাআল্লাহ।\n\nবিঃদ্রঃ চেষ্টা করবেন প্রতিদিন কমপক্ষে ১০০০ বার ইস্তেগফার এবং ১০০০ বার দুরুদ পড়তে। এর চেয়ে যত বেশি সম্ভব হয় পড়তে পারেন। মনে রাখবেন যত বেশি পড়বেন ততই উপকৃত হবেন ইনশাআল্লাহ্।",
